local ports = require("src.foundation.ports.runtime_ports")
describe("teardown leak", function()
  describe("polluter", function()
    after_each(function() ports.reset_for_tests() end)
    it("passes its body then leaks", function() assert.is_true(ports.is_configured()) end)
  end)
  describe("victim", function()
    it("sees restored ports", function() assert.is_true(ports.is_configured()) end)
  end)
end)
